package com.gym.management.service;
import com.gym.management.dto.MemberFitnessDtos.NotificationDto;import com.gym.management.entity.*;import com.gym.management.exception.NotFoundException;import com.gym.management.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @Transactional
public class MemberNotificationService{
 private final GymUserRepository users;private final MemberNotificationRepository notifications;private final GymAnnouncementRepository announcements;
 public MemberNotificationService(GymUserRepository users,MemberNotificationRepository notifications,GymAnnouncementRepository announcements){this.users=users;this.notifications=notifications;this.announcements=announcements;}
 private Member member(String username){GymUser u=users.findByUsernameIgnoreCase(username).orElseThrow(()->new NotFoundException("Member account not found"));if(u.getRole()!=Role.MEMBER||u.getMember()==null)throw new NotFoundException("Member account not found");return u.getMember();}
 public List<NotificationDto> list(String username){Member m=member(username);synchronize(m);return notifications.findTop100ByMemberIdOrderByCreatedAtDesc(m.getId()).stream().map(n->new NotificationDto(n.getId(),n.getCategory(),n.getTitle(),n.getMessage(),n.getCreatedAt(),n.isRead(),n.getAnnouncement()==null?null:n.getAnnouncement().getId())).toList();}
 public long unreadCount(String username){Member m=member(username);synchronize(m);return notifications.countByMemberIdAndReadAtIsNull(m.getId());}
 private void synchronize(Member m){LocalDate today=LocalDate.now();LocalDate expiry=m.getMembershipEnd();for(MemberNotification old:notifications.findByMemberIdAndCategory(m.getId(),"MEMBERSHIP"))if(expiry==null||!old.getDedupeKey().endsWith(":"+expiry))notifications.delete(old);if(expiry!=null){long days=java.time.temporal.ChronoUnit.DAYS.between(today,expiry);if(days==7)add(m,"MEMBERSHIP","Membership expires soon","Your membership expires in 7 days.","membership:"+m.getId()+":7:"+expiry);else if(days==1)add(m,"MEMBERSHIP","Membership expires tomorrow","Your membership expires tomorrow.","membership:"+m.getId()+":1:"+expiry);else if(days<0)add(m,"MEMBERSHIP","Membership expired","Your membership expired on "+expiry+". Contact the gym to renew.","membership:"+m.getId()+":expired:"+expiry);}
  LocalDateTime now=LocalDateTime.now();for(GymAnnouncement a:announcements.findByActiveTrueAndStartsAtLessThanEqualAndAudienceInOrderByStartsAtDesc(now,List.of("ALL","MEMBERS"))){if(a.getEndsAt()!=null&&a.getEndsAt().isBefore(now))continue;String key="announcement:"+m.getId()+":"+a.getId();if(!notifications.existsByDedupeKey(key))notifications.save(new MemberNotification(m,a,"ANNOUNCEMENT",a.getTitle(),a.getMessage(),key));}
 }
 private void add(Member m,String category,String title,String message,String key){if(!notifications.existsByDedupeKey(key))notifications.save(new MemberNotification(m,category,title,message,key));}
 public NotificationDto markRead(String username,Long id){Member m=member(username);MemberNotification n=notifications.findByIdAndMemberId(id,m.getId()).orElseThrow(()->new NotFoundException("Notification not found"));n.markRead();return dto(n);}
 public void markAllRead(String username){Member m=member(username);notifications.findByMemberIdAndReadAtIsNull(m.getId()).forEach(MemberNotification::markRead);}
 private NotificationDto dto(MemberNotification n){return new NotificationDto(n.getId(),n.getCategory(),n.getTitle(),n.getMessage(),n.getCreatedAt(),n.isRead(),n.getAnnouncement()==null?null:n.getAnnouncement().getId());}
}
